// Stimulus-driven XSim bench for m7_enc_uart_axil (2026-10-11).
//
// Plays +STIM=<file> generated by tools/enc_uart_model.py gen, drives the UART
// line bit by bit, logs every odometry update (read through AXI with the
// UPDATE_COUNT seqlock) and the final counters to +LOG=<file>. The verdict is
// given by `enc_uart_model.py check`, which predicts counters from the
// stimulus and recomputes every odometry value with the normative model.
// Stimulus lines:  B idle bit_cycles byte stop_ok | G idle low_cycles 00 0 |
//                  W idle addr(dec) data(hex) 0   | E idle 0 00 0
module tb_m7_enc_uart;
    parameter integer CLK_HZ   = 11520000;
    parameter integer BAUD     = 115200;
    parameter integer BYTE_GAP = 11520;
    parameter integer LINK_TO  = 576000;
    parameter integer MAX_DT   = 1152000;

    logic clk = 0, rstn = 0;
    always #5 clk = ~clk;
    logic [15:0] awaddr = 0, araddr = 0;
    logic        awvalid = 0, wvalid = 0, bready = 0, arvalid = 0, rready = 0;
    logic [31:0] wdata = 0;
    wire         awready, wready, bvalid, arready, rvalid;
    wire [31:0]  rdata;
    wire [1:0]   bresp, rresp;
    logic        rx = 1'b1;
    wire [63:0]  timebase;
    wire         irq;
    int errors = 0;

    m7_timebase u_tb (.clk(clk), .rst_n(rstn), .timebase(timebase));
    m7_enc_uart_axil #(.CLK_HZ(CLK_HZ), .BAUD(BAUD), .BYTE_GAP_CYCLES(BYTE_GAP),
                       .LINK_TIMEOUT_CYCLES(LINK_TO), .MAX_DT_DEFAULT(MAX_DT)) dut (
        .s_axi_aclk(clk), .s_axi_aresetn(rstn),
        .s_axi_awaddr(awaddr), .s_axi_awprot(3'b0), .s_axi_awvalid(awvalid), .s_axi_awready(awready),
        .s_axi_wdata(wdata), .s_axi_wstrb(4'hF), .s_axi_wvalid(wvalid), .s_axi_wready(wready),
        .s_axi_bresp(bresp), .s_axi_bvalid(bvalid), .s_axi_bready(bready),
        .s_axi_araddr(araddr), .s_axi_arprot(3'b0), .s_axi_arvalid(arvalid), .s_axi_arready(arready),
        .s_axi_rdata(rdata), .s_axi_rresp(rresp), .s_axi_rvalid(rvalid), .s_axi_rready(rready),
        .uart_rx_i(rx), .timebase_i(timebase), .irq(irq));

    longint cyc = 0;
    always @(posedge clk) cyc <= cyc + 1;

    semaphore bus = new(1);
    task automatic wr(input [15:0] a, input [31:0] v);
        bus.get(1);
        @(negedge clk); awaddr = a; wdata = v; awvalid = 1; wvalid = 1; bready = 1;
        do @(posedge clk); while (!(awready && wready));
        @(negedge clk); awvalid = 0; wvalid = 0;
        while (!bvalid) @(posedge clk);
        if (bresp != 0) begin $display("ERROR bresp @%h", a); errors++; end
        @(negedge clk); bready = 0;
        bus.put(1);
    endtask
    task automatic rd_raw(input [15:0] a, output [31:0] v);
        @(negedge clk); araddr = a; arvalid = 1; rready = 1;
        do @(posedge clk); while (!arready);
        @(negedge clk); arvalid = 0;
        while (!rvalid) @(posedge clk);
        v = rdata;
        if (rresp != 0) begin $display("ERROR rresp @%h", a); errors++; end
        @(negedge clk); rready = 0;
    endtask
    task automatic rd(input [15:0] a, output [31:0] v);
        bus.get(1); rd_raw(a, v); bus.put(1);
    endtask
    function automatic longint unsigned u64(input [31:0] hi, input [31:0] lo);
        return {hi, lo};
    endfunction

    int log_fd;
    string stim_path, log_path;
    bit done_stim = 0;

    // ---------------- odometry monitor: one ODOM line per update ----------------
    initial begin : monitor
        logic [31:0] u1, u2, ts_lo, ts_hi, sq, l, r, of, vl, vr, vc, dll, dlh, drl, drh,
                     dcl, dch, hd, dt, cll, clh, crl, crh;
        int tries;
        wait (rstn === 1'b1);
        forever begin
            @(posedge clk iff irq === 1'b1);
            tries = 0;
            bus.get(1);
            do begin
                rd_raw(16'h0024, u1);
                rd_raw(16'h0028, ts_lo); rd_raw(16'h002C, ts_hi); rd_raw(16'h0030, sq);
                rd_raw(16'h0034, l); rd_raw(16'h0038, r); rd_raw(16'h003C, of);
                rd_raw(16'h0040, vl); rd_raw(16'h0044, vr); rd_raw(16'h0048, vc);
                rd_raw(16'h004C, dll); rd_raw(16'h0050, dlh); rd_raw(16'h0054, drl); rd_raw(16'h0058, drh);
                rd_raw(16'h005C, dcl); rd_raw(16'h0060, dch); rd_raw(16'h0064, hd); rd_raw(16'h0068, dt);
                rd_raw(16'h00B8, cll); rd_raw(16'h00BC, clh); rd_raw(16'h00C0, crl); rd_raw(16'h00C4, crh);
                rd_raw(16'h0024, u2);
                tries++;
            end while (u1 != u2 && tries < 4);
            // W1C the odometry bit (inline: the semaphore is held)
            @(negedge clk); awaddr = 16'h0098; wdata = 32'h1; awvalid = 1; wvalid = 1; bready = 1;
            do @(posedge clk); while (!(awready && wready));
            @(negedge clk); awvalid = 0; wvalid = 0;
            while (!bvalid) @(posedge clk);
            @(negedge clk); bready = 0;
            bus.put(1);
            if (u1 != u2) begin $display("ERROR seqlock never stable"); errors++; end
            $fdisplay(log_fd, "ODOM %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d",
                      u1, u64(ts_hi, ts_lo), sq[7:0], sq[31:16], sq[15:8], l, r, of, vl, vr, vc,
                      u64(dlh, dll), u64(drh, drl), u64(dch, dcl), hd, dt, u64(clh, cll), u64(crh, crl));
        end
    end

    // ---------------- stimulus player ----------------
    task automatic drive_bit(input logic v, input int n);
        @(posedge clk); #1 rx = v;
        repeat (n - 1) @(posedge clk);
    endtask

    initial begin
        int fd, code, idle, a2, ok, nb;
        string kind;
        logic [31:0] dat, v;
        if (!$value$plusargs("STIM=%s", stim_path)) $fatal(1, "need +STIM=");
        if (!$value$plusargs("LOG=%s", log_path)) $fatal(1, "need +LOG=");
        fd = $fopen(stim_path, "r");
        log_fd = $fopen(log_path, "w");
        if (fd == 0 || log_fd == 0) $fatal(1, "cannot open stim/log");
        $fdisplay(log_fd, "CFG %0d %0d %0d %0d %0d", CLK_HZ, BAUD, BYTE_GAP, LINK_TO, MAX_DT);
        repeat (10) @(posedge clk);
        rstn = 1;
        repeat (4) @(posedge clk); #1;
        $fdisplay(log_fd, "TBOFF %0d", cyc - longint'(timebase));
        rd(16'h0000, v);
        if (v !== 32'h4D37454E) begin $display("ERROR MAGIC %h", v); errors++; end
        rd(16'h00A4, v);
        if (v !== (CLK_HZ + BAUD / 2) / BAUD) begin $display("ERROR BAUD_DIV %0d", v); errors++; end
        wr(16'h009C, 32'h1);              // irq on odometry update
        nb = 0;
        while (!$feof(fd)) begin
            code = $fscanf(fd, "%s %d %d %h %d\n", kind, idle, a2, dat, ok);
            if (code != 5) break;
            repeat (idle) @(posedge clk);
            case (kind)
                "B": begin
                    @(posedge clk); #1 rx = 1'b0;
                    $fdisplay(log_fd, "TXB %0d %0d %0d", nb, cyc, a2);
                    nb++;
                    repeat (a2 - 1) @(posedge clk);
                    for (int i = 0; i < 8; i++) drive_bit(dat[i], a2);
                    drive_bit(ok[0], a2);
                    if (!ok[0]) drive_bit(1'b1, a2);
                    @(posedge clk); #1 rx = 1'b1;
                end
                "G": begin
                    @(posedge clk); #1 rx = 1'b0;
                    repeat (a2) @(posedge clk);
                    #1 rx = 1'b1;
                end
                "W": wr(a2[15:0], dat);
                "E": ;
                default: begin $display("ERROR bad stim line kind %s", kind); errors++; end
            endcase
        end
        $fclose(fd);
        repeat (2000) @(posedge clk);
        begin
            logic [31:0] c[11];
            for (int i = 0; i < 11; i++) rd(16'h006C + 4 * i, c[i]);
            $fdisplay(log_fd, "CNT %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d",
                      c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7], c[8], c[9], c[10]);
        end
        $fdisplay(log_fd, "BENCH_ERRORS %0d", errors);
        $fclose(log_fd);
        $display("TB_M7_ENC_UART DONE bench_errors=%0d bytes=%0d", errors, nb);
        $finish;
    end
endmodule
